import os, runpy, sys
name = sys.argv[1] if len(sys.argv) > 1 else ''
mode = sys.argv[2] if len(sys.argv) > 2 else ''
d, p = os.getcwd(), ''
while True:
    c = os.path.join(d, '.claude', 'hooks', name)
    if os.path.isfile(c):
        p = c
        break
    n = os.path.dirname(d)
    if n == d:
        break
    d = n
if p:
    sys.argv = [p, mode]
    try:
        runpy.run_path(p, run_name='__main__')
    except BaseException:
        pass
sys.exit(0)

